import React, { useEffect, useMemo, useState } from "react";
import Modal from "./Modal";

export interface PromptNumberModalProps {
    isOpen: boolean;
    title: string;
    label: string;
    description?: React.ReactNode;
    defaultValue: number;
    min?: number;
    max?: number;
    confirmText?: string;
    cancelText?: string;
    isBusy?: boolean;
    onConfirm: (value: number) => void;
    onCancel: () => void;
}

export default function PromptNumberModal({
    isOpen,
    title,
    label,
    description,
    defaultValue,
    min = 1,
    max = 365,
    confirmText = "Potvrdi",
    cancelText = "Otka�i",
    isBusy = false,
    onConfirm,
    onCancel,
}: PromptNumberModalProps) {
    const [rawValue, setRawValue] = useState<string>(String(defaultValue));

    useEffect(() => {
        if (isOpen) setRawValue(String(defaultValue));
    }, [isOpen, defaultValue]);

    const parsed = useMemo(() => {
        const n = Number(rawValue);
        return Number.isFinite(n) ? n : NaN;
    }, [rawValue]);

    const validationError = useMemo(() => {
        if (!rawValue.trim()) return "Vrednost je obavezna.";
        if (!Number.isFinite(parsed)) return "Unesite ispravan broj.";
        if (!Number.isInteger(parsed)) return "Unesite ceo broj.";
        if (parsed < min) return `Minimalna vrednost je ${min}.`;
        if (parsed > max) return `Maksimalna vrednost je ${max}.`;
        return null;
    }, [rawValue, parsed, min, max]);

    const canConfirm = !validationError && !isBusy;

    return (
        <Modal
            isOpen={isOpen}
            onClose={onCancel}
            title={title}
            size="sm"
            footer={
                <>
                    <button
                        type="button"
                        className="button-big button-secondary"
                        onClick={onCancel}
                        disabled={isBusy}
                    >
                        {cancelText}
                    </button>
                    <button
                        type="button"
                        className="button-big"
                        style={{ boxShadow: "none" }}
                        onClick={() => onConfirm(parsed)}
                        disabled={!canConfirm}
                    >
                        {isBusy ? "Radim..." : confirmText}
                    </button>
                </>
            }
        >
            {description && (
                <div className="mb-3 text-sm text-muted" style={{ lineHeight: 1.5 }}>{description}</div>
            )}

            <label className="field-label" style={{ marginTop: 0 }}>
                {label}
            </label>
            <input
                className="input-big"
                type="number"
                inputMode="numeric"
                value={rawValue}
                onChange={(e) => setRawValue(e.target.value)}
                min={min}
                max={max}
                step={1}
                autoFocus
            />

            {validationError && (
                <div className="mt-2">
                    <span className="error-msg block">{validationError}</span>
                </div>
            )}
        </Modal>
    );
}
