import { useState, useMemo, useCallback, useEffect, useRef } from "react";
import { KreirajProdajuDto } from "../../types/prodaja/prodaja";
import { useToast } from "../Toast";

type ArtikalOption = { id: number; naziv: string; cena: number };

interface CreateProdajaFormProps {
    artikli: ArtikalOption[];
    onSearchArtikli?: (query: string) => Promise<ArtikalOption[]>;
    onSubmit: (data: KreirajProdajuDto) => Promise<void>;
}

function safeNumber(value: unknown, fallback = 0) {
    const n = typeof value === "number" ? value : Number(value);
    return Number.isFinite(n) ? n : fallback;
}

function mergeArtikli(base: ArtikalOption[], incoming: ArtikalOption[]) {
    const map = new Map<number, ArtikalOption>();
    for (const x of base) map.set(x.id, x);
    for (const x of incoming) map.set(x.id, x);
    return Array.from(map.values()).sort((a, b) => a.naziv.localeCompare(b.naziv, "sr-Latn", { sensitivity: "base" }));
}

function normalizeRacun(value: string): string {
    return value.trim();
}

function buildNextRacunSuggestion(value: string): string | null {
    const trimmed = normalizeRacun(value);
    if (!trimmed) return null;

    const match = trimmed.match(/^(.*?)(\d+)(\D*)$/);
    if (!match) return null;

    const [, prefix, digits, suffix] = match;
    const next = (Number(digits) + 1).toString().padStart(digits.length, "0");
    return `${prefix}${next}${suffix}`;
}

export default function CreateProdajaForm({ artikli, onSearchArtikli, onSubmit }: CreateProdajaFormProps) {
    const toast = useToast();

    const [knownArtikli, setKnownArtikli] = useState<ArtikalOption[]>(artikli);
    const [brojRacuna, setBrojRacuna] = useState("");
    const [stavke, setStavke] = useState<{ idArtikal: number; kolicina: number; cena: number }[]>([
        { idArtikal: artikli[0]?.id ?? 0, kolicina: 1, cena: artikli[0]?.cena ?? 0 },
    ]);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const artikalOptions = useMemo(() => {
        return knownArtikli.map((a) => (
            <option key={a.id} value={a.id}>
                {a.naziv} - {a.cena} RSD
            </option>
        ));
    }, [knownArtikli]);

    const [searchQuery, setSearchQuery] = useState("");
    const [debouncedQuery, setDebouncedQuery] = useState("");
    const [showSearchResults, setShowSearchResults] = useState(false);
    const [selectedIndex, setSelectedIndex] = useState(0);
    const [filteredArtikli, setFilteredArtikli] = useState<ArtikalOption[]>([]);
    const [isSearching, setIsSearching] = useState(false);
    const searchRef = useRef<HTMLDivElement>(null);
    const remoteSearchSeq = useRef(0);

    useEffect(() => {
        setKnownArtikli((prev) => mergeArtikli(prev, artikli));
    }, [artikli]);

    useEffect(() => {
        if (!knownArtikli.length) return;
        setStavke((prev) => {
            if (!prev.length) {
                return [{ idArtikal: knownArtikli[0].id, kolicina: 1, cena: knownArtikli[0].cena }];
            }
            return prev.map((s, idx) => {
                if (idx === 0 && s.idArtikal === 0) {
                    return { ...s, idArtikal: knownArtikli[0].id, cena: knownArtikli[0].cena };
                }
                return s;
            });
        });
    }, [knownArtikli]);

    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedQuery(searchQuery);
        }, 250);
        return () => clearTimeout(timer);
    }, [searchQuery]);

    useEffect(() => {
        if (onSearchArtikli) return;
        const q = debouncedQuery.trim().toLowerCase();
        if (!q) {
            setFilteredArtikli([]);
            setIsSearching(false);
            return;
        }
        const local = knownArtikli
            .filter((a) => a.naziv.toLowerCase().includes(q))
            .slice(0, 10);
        setFilteredArtikli(local);
        setIsSearching(false);
    }, [debouncedQuery, knownArtikli, onSearchArtikli]);

    useEffect(() => {
        if (!onSearchArtikli) return;
        const q = debouncedQuery.trim();
        if (!q) {
            setFilteredArtikli([]);
            setIsSearching(false);
            return;
        }

        const seq = ++remoteSearchSeq.current;
        let cancelled = false;
        setIsSearching(true);

        onSearchArtikli(q)
            .then((rows) => {
                if (cancelled || seq !== remoteSearchSeq.current) return;
                const data = (rows ?? []).slice(0, 20);
                setFilteredArtikli(data);
                if (data.length > 0) {
                    setKnownArtikli((prev) => mergeArtikli(prev, data));
                }
            })
            .catch((err) => {
                if (cancelled || seq !== remoteSearchSeq.current) return;
                console.error("Search artikli failed:", err);
                setFilteredArtikli([]);
            })
            .finally(() => {
                if (!cancelled && seq === remoteSearchSeq.current) {
                    setIsSearching(false);
                }
            });

        return () => {
            cancelled = true;
        };
    }, [debouncedQuery, onSearchArtikli]);

    useEffect(() => {
        setSelectedIndex(0);
    }, [filteredArtikli.length]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
                setShowSearchResults(false);
            }
        };

        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    const addStavka = () =>
        setStavke((s) => [
            ...s,
            { idArtikal: knownArtikli[0]?.id ?? 0, kolicina: 1, cena: knownArtikli[0]?.cena ?? 0 },
        ]);

    const quickAddArtikal = useCallback((artikal: ArtikalOption) => {
        setKnownArtikli((prev) => mergeArtikli(prev, [artikal]));
        setStavke((s) => [...s, { idArtikal: artikal.id, kolicina: 1, cena: safeNumber(artikal.cena, 0) }]);
        setSearchQuery("");
        setShowSearchResults(false);
        setSelectedIndex(0);
    }, []);

    const removeStavka = (index: number) => setStavke((s) => s.filter((_, i) => i !== index));

    const updateStavka = (
        index: number,
        patch: Partial<{ idArtikal: number; kolicina: number; cena: number }>
    ) =>
        setStavke((s) => {
            const copy = [...s];
            const prev = copy[index];

            const next = {
                ...prev,
                ...patch,
                kolicina: safeNumber(patch.kolicina ?? prev.kolicina, 1),
                cena: safeNumber(patch.cena ?? prev.cena, 0),
            };

            copy[index] = next;
            return copy;
        });

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (!showSearchResults || filteredArtikli.length === 0) return;

        switch (e.key) {
            case "ArrowDown":
                e.preventDefault();
                setSelectedIndex((prev) => (prev + 1) % filteredArtikli.length);
                break;
            case "ArrowUp":
                e.preventDefault();
                setSelectedIndex((prev) => (prev - 1 + filteredArtikli.length) % filteredArtikli.length);
                break;
            case "Enter":
                e.preventDefault();
                if (filteredArtikli[selectedIndex]) {
                    quickAddArtikal(filteredArtikli[selectedIndex]);
                }
                break;
            case "Escape":
                setShowSearchResults(false);
                break;
        }
    };

    const handleSubmit = async () => {
        setError(null);

        const normalizedRacun = normalizeRacun(brojRacuna);
        if (normalizedRacun.length < 3) {
            setError("Broj racuna mora imati najmanje 3 karaktera.");
            return;
        }

        if (!stavke.length) {
            setError("Dodajte bar jednu stavku.");
            return;
        }

        if (invalidStavkeCount > 0) {
            setError("Proverite stavke: kolicina mora biti > 0 i cena ne moze biti negativna.");
            return;
        }

        const payload: KreirajProdajuDto = {
            brojRacuna: normalizedRacun,
            idObjekat: 1,
            nacinPlacanja: "Gotovina",
            stavke: stavke.map((s) => ({
                ...s,
                kolicina: Math.max(1, Math.trunc(safeNumber(s.kolicina, 1))),
                cena: safeNumber(s.cena, 0),
            })),
        };

        setIsSubmitting(true);
        try {
            await onSubmit(payload);
            setBrojRacuna("");
            setStavke([{ idArtikal: knownArtikli[0]?.id ?? 0, kolicina: 1, cena: knownArtikli[0]?.cena ?? 0 }]);
            toast.success("Prodaja uspesna");
        } catch (err: unknown) {
            console.error(err);
            const msg = err instanceof Error ? err.message : "Greska pri kreiranju prodaje";
            setError(msg);
            toast.error(msg);
        } finally {
            setIsSubmitting(false);
        }
    };

    const ukupno = useMemo(() => {
        return stavke.reduce((sum, s) => sum + safeNumber(s.kolicina, 0) * safeNumber(s.cena, 0), 0);
    }, [stavke]);

    const invalidStavkeCount = useMemo(() => {
        return stavke.filter((s) => safeNumber(s.kolicina, 0) <= 0 || safeNumber(s.cena, 0) < 0 || s.idArtikal <= 0).length;
    }, [stavke]);

    const racunSuggestions = useMemo(() => {
        const suggestions = new Set<string>();
        const next = buildNextRacunSuggestion(brojRacuna);
        if (next) suggestions.add(next);
        if (!normalizeRacun(brojRacuna)) {
            suggestions.add(`POS-${new Date().getFullYear()}-001`);
        }
        return Array.from(suggestions).slice(0, 4);
    }, [brojRacuna]);

    const canSubmit =
        normalizeRacun(brojRacuna).length >= 3 &&
        stavke.length > 0 &&
        invalidStavkeCount === 0 &&
        !isSubmitting;

    useEffect(() => {
        const onWindowKeyDown = (event: KeyboardEvent) => {
            if ((event.ctrlKey || event.metaKey) && event.key === "Enter" && canSubmit) {
                event.preventDefault();
                void handleSubmit();
            }
        };

        window.addEventListener("keydown", onWindowKeyDown);
        return () => window.removeEventListener("keydown", onWindowKeyDown);
    }, [canSubmit, handleSubmit]);

    return (
        <div className="space-y-4">
            <section className="rounded-xl border border-border bg-surface p-4">
                <h2 className="mb-4 text-xl font-semibold text-foreground">Nova prodaja</h2>
                <div className="mb-3 grid gap-2 md:grid-cols-3">
                    <div className={`rounded-lg border px-3 py-2 text-xs ${normalizeRacun(brojRacuna).length >= 3 ? "border-emerald-700 bg-emerald-950/20 text-emerald-300" : "border-border bg-surface text-muted"}`}>
                        Broj racuna
                    </div>
                    <div className={`rounded-lg border px-3 py-2 text-xs ${stavke.length > 0 ? "border-emerald-700 bg-emerald-950/20 text-emerald-300" : "border-border bg-surface text-muted"}`}>
                        Stavke: {stavke.length}
                    </div>
                    <div className={`rounded-lg border px-3 py-2 text-xs ${invalidStavkeCount === 0 ? "border-emerald-700 bg-emerald-950/20 text-emerald-300" : "border-amber-700 bg-amber-950/20 text-amber-300"}`}>
                        Validacija: {invalidStavkeCount === 0 ? "OK" : `${invalidStavkeCount} problema`}
                    </div>
                </div>

                <label className="mb-1 block text-xs uppercase tracking-wide text-muted">Broj racuna *</label>
                <input
                    placeholder="Broj racuna"
                    value={brojRacuna}
                    onChange={(e) => setBrojRacuna(e.target.value)}
                    className="w-full rounded-xl border border-border bg-surface px-3 py-2 text-sm text-foreground outline-none transition focus:border-primary"
                />
                {racunSuggestions.length > 0 && (
                    <div className="mt-2 flex flex-wrap gap-2">
                        {racunSuggestions.map((suggestion) => (
                            <button
                                key={suggestion}
                                type="button"
                                onClick={() => setBrojRacuna(suggestion)}
                                className="rounded-full border border-border bg-surface px-2.5 py-1 text-[11px] text-muted hover:border-primary hover:text-foreground"
                            >
                                {suggestion}
                            </button>
                        ))}
                    </div>
                )}
                <p className="mt-2 text-xs text-muted">Tip: `Ctrl+Enter` cuva prodaju kada je forma validna.</p>
            </section>

            <section className="relative rounded-xl border border-border bg-surface p-4" ref={searchRef}>
                <label className="mb-1 block text-xs uppercase tracking-wide text-muted">Pretrazi i dodaj artikal</label>
                <input
                    type="text"
                    placeholder="Pretrazi artikle po nazivu..."
                    value={searchQuery}
                    onChange={(e) => {
                        setSearchQuery(e.target.value);
                        setShowSearchResults(true);
                    }}
                    onFocus={() => setShowSearchResults(true)}
                    onKeyDown={handleKeyDown}
                    className="w-full rounded-xl border border-border bg-surface px-3 py-2 text-sm text-foreground outline-none transition focus:border-primary"
                />

                {showSearchResults && searchQuery.trim() && (
                    <div className="absolute left-4 right-4 top-[calc(100%-4px)] z-20 mt-2 max-h-80 overflow-y-auto rounded-xl border border-border bg-surface shadow-xl">
                        {isSearching ? (
                            <div className="px-3 py-5 text-center text-sm text-muted">Pretrazujem...</div>
                        ) : filteredArtikli.length > 0 ? (
                            filteredArtikli.map((art, idx) => (
                                    <button
                                    key={art.id}
                                    type="button"
                                    onClick={() => quickAddArtikal(art)}
                                        className={`flex w-full items-center justify-between border-b border-border px-3 py-3 text-left transition ${idx === selectedIndex ? "bg-surface-elevated" : "hover:bg-surface-elevated"}`}
                                    onMouseEnter={() => setSelectedIndex(idx)}
                                >
                                    <div>
                                        <div className="font-semibold text-foreground">{art.naziv}</div>
                                        <div className="text-xs text-muted">ID: {art.id}</div>
                                    </div>
                                    <div className="text-sm font-semibold text-success">{art.cena} RSD</div>
                                </button>
                            ))
                        ) : (
                            <div className="px-3 py-5 text-center text-sm text-muted">Nema rezultata za "{searchQuery}"</div>
                        )}
                    </div>
                )}
            </section>

            <section className="rounded-xl border border-border bg-surface p-4">
                <div className="mb-3 flex items-center justify-between">
                    <h3 className="text-sm font-semibold uppercase tracking-wide text-muted">Stavke ({stavke.length})</h3>
                    <button
                        type="button"
                        onClick={addStavka}
                        className="rounded-lg border px-3 py-1.5 text-xs font-semibold border-success bg-success-10 text-success hover:bg-success"
                    >
                        + Dodaj stavku
                    </button>
                </div>

                <div className="space-y-3">
                    {stavke.map((s, i) => (
                        <div key={i} className="grid gap-2 rounded-lg border border-border bg-surface p-3 lg:grid-cols-[1.7fr_0.7fr_0.8fr_0.8fr_auto]"> 
                            <div>
                                <label className="mb-1 block text-xs text-muted">Artikal</label>
                                <select
                                    value={s.idArtikal}
                                    onChange={(e) => {
                                        const id = Number(e.target.value);
                                        const art = knownArtikli.find((a) => a.id === id);
                                        updateStavka(i, { idArtikal: id, cena: art?.cena ?? s.cena });
                                    }}
                                    className="w-full rounded-lg border border-border bg-surface px-2 py-2 text-sm text-foreground"
                                >
                                    {artikalOptions}
                                </select>
                            </div>

                            <div>
                                <label className="mb-1 block text-xs text-muted">Kolicina</label>
                                <input
                                    type="number"
                                    min={1}
                                    value={s.kolicina}
                                    onChange={(e) => updateStavka(i, { kolicina: Number(e.target.value) })}
                                    className="w-full rounded-lg border border-border bg-surface px-2 py-2 text-sm text-foreground"
                                />
                            </div>

                            <div>
                                <label className="mb-1 block text-xs text-muted">Cena</label>
                                <input
                                    type="number"
                                    min={0}
                                    value={s.cena}
                                    onChange={(e) => updateStavka(i, { cena: Number(e.target.value) })}
                                    className="w-full rounded-lg border border-border bg-surface px-2 py-2 text-sm text-foreground"
                                />
                            </div>

                            <div>
                                <label className="mb-1 block text-xs text-muted">Iznos</label>
                                <div className="rounded-lg border border-border bg-surface px-2 py-2 text-sm font-semibold text-success">
                                    {(safeNumber(s.kolicina, 0) * safeNumber(s.cena, 0)).toFixed(2)} RSD
                                </div>
                            </div>

                            <div className="flex items-end">
                                <button
                                    type="button"
                                    onClick={() => removeStavka(i)}
                                    className="rounded-lg border border-danger bg-danger-10 px-3 py-2 text-xs font-semibold text-danger"
                                >
                                    Ukloni
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            </section>

            <section className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border bg-surface p-4">
                <div className="text-base font-semibold text-foreground">Ukupno: <span className="text-success">{safeNumber(ukupno, 0).toFixed(2)} RSD</span></div>
                <button
                    type="button"
                    onClick={handleSubmit}
                    disabled={!canSubmit}
                    className="rounded-xl border border-primary bg-primary px-4 py-2 text-sm font-semibold text-on-primary transition hover:bg-primary-hover disabled:opacity-60"
                >
                    {isSubmitting ? "Kreiram..." : "Sacuvaj prodaju"}
                </button>
            </section>

            {error && <p className="rounded-lg border border-danger bg-danger-10 px-3 py-2 text-sm text-danger">{error}</p>}
        </div>
    );
}
